CREATE TABLE android_oidc_ciphertext(id TEXT PRIMARY KEY,purpose TEXT NOT NULL,scope TEXT NOT NULL,sealed TEXT NOT NULL,plain_sha256 TEXT NOT NULL,created_at BIGINT NOT NULL,key_instance TEXT NOT NULL);
CREATE TABLE android_oidc_profiles(id TEXT PRIMARY KEY,organization_id TEXT REFERENCES identity_organizations(id),name TEXT NOT NULL,revision BIGINT NOT NULL,epoch TEXT NOT NULL,config_sha256 TEXT NOT NULL,config TEXT NOT NULL,active BIGINT NOT NULL,secret_id TEXT REFERENCES android_oidc_ciphertext(id));
CREATE TABLE android_oidc_profile_operations(owner_id TEXT NOT NULL REFERENCES identity_subjects(id),request_id TEXT NOT NULL,profile_id TEXT NOT NULL REFERENCES android_oidc_profiles(id),request_mac TEXT NOT NULL,receipt_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),PRIMARY KEY(owner_id,request_id));
CREATE TABLE android_oidc_external_identities(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES android_oidc_profiles(id),issuer TEXT NOT NULL,subject TEXT NOT NULL,identity_id TEXT NOT NULL REFERENCES identity_subjects(id),revision BIGINT NOT NULL,active BIGINT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(profile_id,issuer,subject));
CREATE TABLE android_oidc_flows(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,profile_id TEXT NOT NULL REFERENCES android_oidc_profiles(id),profile_revision BIGINT NOT NULL,profile_epoch TEXT NOT NULL,config_sha256 TEXT NOT NULL,organization_epoch BIGINT NOT NULL,purpose TEXT NOT NULL,device_id TEXT NOT NULL,state_sha256 TEXT NOT NULL,resume_sha256 TEXT NOT NULL,request_mac TEXT NOT NULL,link_owner_id TEXT REFERENCES identity_subjects(id),link_session_id TEXT REFERENCES identity_sessions(id),link_session_revision BIGINT NOT NULL,link_identity_revision BIGINT NOT NULL,payload_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,phase TEXT NOT NULL,sso_revision BIGINT NOT NULL DEFAULT 0,sso_epoch TEXT);
CREATE TABLE android_oidc_exchanges(flow_id TEXT PRIMARY KEY REFERENCES android_oidc_flows(id),dispatch_nonce TEXT NOT NULL,code_sha256 TEXT NOT NULL,request_sha256 TEXT NOT NULL,state TEXT NOT NULL,response_id TEXT REFERENCES android_oidc_ciphertext(id),response_sha256 TEXT,response_status BIGINT,dispatched_at BIGINT NOT NULL,received_at BIGINT NOT NULL DEFAULT 0,producer_finished_at BIGINT NOT NULL DEFAULT 0,producer_outcome TEXT NOT NULL DEFAULT 'not_returned');
CREATE TABLE android_oidc_receipts(flow_id TEXT PRIMARY KEY REFERENCES android_oidc_flows(id),identity_id TEXT NOT NULL REFERENCES identity_subjects(id),session_id TEXT NOT NULL REFERENCES identity_sessions(id),external_identity_id TEXT NOT NULL REFERENCES android_oidc_external_identities(id),payload_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),receipt_sha256 TEXT NOT NULL,committed_at BIGINT NOT NULL);
CREATE TABLE android_oidc_flow_closures(flow_id TEXT PRIMARY KEY REFERENCES android_oidc_flows(id),request_id TEXT NOT NULL UNIQUE,request_mac TEXT NOT NULL,receipt_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),created_at BIGINT NOT NULL);
CREATE TABLE android_oidc_compat_flows(flow_id TEXT PRIMARY KEY REFERENCES android_oidc_flows(id),state_sha256 TEXT NOT NULL UNIQUE,payload_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),operator_revision BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE android_oidc_session_origins(session_id TEXT PRIMARY KEY REFERENCES identity_sessions(id),identity_id TEXT NOT NULL REFERENCES identity_subjects(id),profile_id TEXT NOT NULL REFERENCES android_oidc_profiles(id),external_identity_id TEXT NOT NULL REFERENCES android_oidc_external_identities(id),external_revision BIGINT NOT NULL,profile_revision BIGINT NOT NULL,profile_epoch TEXT NOT NULL,config_sha256 TEXT NOT NULL,organization_epoch BIGINT NOT NULL,source_grant_revision BIGINT NOT NULL,flow_id TEXT NOT NULL REFERENCES android_oidc_flows(id),claims_sha256 TEXT NOT NULL,verified_at BIGINT NOT NULL,authentication_time BIGINT NOT NULL,expires_at BIGINT NOT NULL,sso_revision BIGINT NOT NULL DEFAULT 0,sso_epoch TEXT);
CREATE INDEX android_oidc_origins_profile ON android_oidc_session_origins(profile_id,profile_revision);
CREATE INDEX android_oidc_flows_phase ON android_oidc_flows(phase,expires_at);
CREATE TABLE android_oidc_org_sso(organization_id TEXT PRIMARY KEY REFERENCES identity_organizations(id),revision BIGINT NOT NULL,epoch TEXT NOT NULL,enabled BIGINT NOT NULL,profile_id TEXT REFERENCES android_oidc_profiles(id),auto_provision BIGINT NOT NULL,group_mappings TEXT NOT NULL,config_sha256 TEXT NOT NULL);
CREATE TABLE android_oidc_sso_operations(owner_id TEXT NOT NULL REFERENCES identity_subjects(id),request_id TEXT NOT NULL,organization_id TEXT NOT NULL REFERENCES identity_organizations(id),request_mac TEXT NOT NULL,receipt_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),PRIMARY KEY(owner_id,request_id));
CREATE TABLE android_oidc_membership_origins(membership_id TEXT PRIMARY KEY REFERENCES identity_memberships(id),organization_id TEXT NOT NULL REFERENCES identity_organizations(id),identity_id TEXT NOT NULL REFERENCES identity_subjects(id),profile_id TEXT NOT NULL REFERENCES android_oidc_profiles(id),external_identity_id TEXT NOT NULL REFERENCES android_oidc_external_identities(id),profile_revision BIGINT NOT NULL,external_revision BIGINT NOT NULL,settings_revision BIGINT NOT NULL,settings_epoch TEXT NOT NULL,flow_id TEXT NOT NULL REFERENCES android_oidc_flows(id),claims_sha256 TEXT NOT NULL,groups_sha256 TEXT NOT NULL,role TEXT NOT NULL,membership_revision BIGINT NOT NULL,expires_at BIGINT NOT NULL,active BIGINT NOT NULL);
CREATE TABLE android_oidc_denials(flow_id TEXT PRIMARY KEY REFERENCES android_oidc_flows(id),receipt_id TEXT NOT NULL REFERENCES android_oidc_ciphertext(id),created_at BIGINT NOT NULL);